The plugins file should have a **single export** function, so you'll want to include all of the code necessary within the single export. 

As a side note, we built in native TypeScript support into 4.4.0, so you should be able to remove the TypeScript support setup when you upgrade.

Try the code below which puts all of the code necessary within the single export.

```js
const wp = require('@cypress/webpack-preprocessor')
const ntlmAuth = require("cypress-ntlm-auth/dist/plugin");

module.exports = (on, config) => {
  const options = {
    webpackOptions: {
      resolve: {
        extensions: [".ts", ".tsx", ".js"]
      },
      module: {
        rules: [
          {
            test: /\.tsx?$/,
            loader: "ts-loader",
            options: { transpileOnly: true }
          }
        ]
      }
    },
  }

  on('file:preprocessor', wp(options))

  config = ntlmAuth.initNtlmAuth(config);
  
  return config;
};
