  const homeSubmitBtn = ;

  return {
    homeSubmitBtn: () =>
    cy.get('.homepage-main .button-action-container button[type="submit"]').as('homeSubmitBtn'),
    articleInput: () => cy.get('input[name="article"]').as('articleInput'),
    flowTypeInput,
    flowTypeRSelect,
