Got it, I fixed it. So, like Vue Test Utils, we require you to register your plugins with `createLocalVue`. I would suggest exporting a mount command from a helper that wraps your component... but I'll show you the simple version here. I'll submit a PR onto that repo.

```ts
import { mount } from '@cypress/vue'
import ClickToLazyLoad from '@/components/ClickToLazyLoad.vue'
import { createLocalVue } from '@vue/test-utils'
import VueCompositionAPI from '@vue/composition-api'

// See documentation here https://vue-test-utils.vuejs.org/api/options.html#localvue
const localVue = createLocalVue()
localVue.use(VueCompositionAPI)

describe('ClickToLazyLoad', () => {
  it('loads a component lazily when clicking a button', () => {
    mount(ClickToLazyLoad, { localVue })
    cy.get('button').click()
    cy.get('p').should(
      'have.text',
      `This is a test component to be loaded lazily with import('...')`
    )
  })
})
```

I found a workaround for the problem: Using a `cy.task`, we can execute code in node from the test. I installed `puppeteer-core` and created a task to send arbitrary commands to all targets matching the type `page` or `service-worker`.

Note that Cypress needs to be executed with the `CYPRESS_REMOTE_DEBUGGING_PORT` env variable. 

cypress/plugins/send-devtools-command-to-page-and-service-worker.js
```javascript
const puppeteer = require('puppeteer-core')

module.exports = async ({ command, params }) => {

  console.log(`Plugin executed for command ${command}, params:`, params);

  const remoteDebuggingPort = Number(process.env.CYPRESS_REMOTE_DEBUGGING_PORT);
  const browser = await puppeteer.connect({ browserURL: `http://127.0.0.1:${remoteDebuggingPort}` });

  const targets = (await browser.targets()).filter(target => target.type() === 'page' || target.type() === 'service_worker');

  const sendPromises = targets.map(target => new Promise(async (resolve, reject) => {
    try {
      console.log(`Sending to ${target.type()} at`, target.url());
      const cdpSession = await target.createCDPSession();
      await cdpSession.send(command, params);
      resolve(null);
    } catch(error) {
      reject(error);
    }
  }));

  await Promise.all(sendPromises);

  return null;
}
```

cypress/plugins/index.js
```javascript
const sendDevtoolsCommandToPageAndServiceWorker = require('./send-devtools-command-to-page-and-service-worker');

module.exports = on => {
  on("task", { sendDevtoolsCommandToPageAndServiceWorker })
};

```
cypress/integration/demo.spec.ts
```javascript
describe('Service worker', () => {

  it('caches requests when offline to replay later.', () => {

    cy.task('sendDevtoolsCommandToPageAndServiceWorker', { command: 'Network.enable' });
    cy.task('sendDevtoolsCommandToPageAndServiceWorker', {
