in 7.0.0 we changed the default headless browser resolution to 1920x1080 from 1280x720. based on what @tommasomarchionni has mentioned this could be causing the slow down / crashing. 
Please try reverting back to 1280x720 and seeing if run times go back to normal, here's an example of how to do that
```ts
// cypress/plugins/index.js

/**
 * @type {Cypress.PluginConfig}
 */
module.exports = (on, config) => {
  on('before:browser:launch', (browser, options) => {
    return useFixedBrowserLaunchSize(browser, options, config)
  })
})

function  useFixedBrowserLaunchSize (browser, options) {
    if (browser.family === 'firefox') {
      // (height must account for firefox url bar, which we can only shrink to 1px)
      options.args.push(
        '-width', '1280', '-height', '721',
      )
    } else if (browser.name === 'electron') {
      options.preferences.width = 1280
      options.preferences.height = 720
    } else if (browser.family === 'chromium') {
      options.args.push('--window-size=1280,720')
    }
  return options
}

```

if this fixes the issue for people, we may have to change the default back.

